                  "note": "作者：关汉卿。底本：明《元曲选》本，参照中国古典戏曲资料库《元曲选·救风尘·第一折》。本折写歌女宋引章执意嫁给周舍，赵盼儿以自身经验劝阻；周舍以虚情假意骗取婚姻，赵盼儿最后决定设法救出引章。\n第一折由周舍、宋引章、安秀实和赵盼儿四条人物线交织展开：周舍以婚姻为谋财手段，宋引章沉迷表面体贴，安秀实因失恋转而求仕，赵盼儿则以清醒判断承担救助责任。曲牌整体先议婚姻，再写妓女处境，继而揭露周舍虚情假意，最后以茶引点明其逐利本质。",
