                    "【正宫·端正好】则为他满怀愁。心间闷。做的个进退无门。那婆娘家一涌性无思忖。我可也强打入迷魂阵。",
                    "【滚绣球】我这里微微的把气喷。输个姓因。怎不教那厮背槽抛粪。更做道普天下无他这等郎君。想着容易情忒献勤。几番家待要不问。第一来我则是可怜见无主娘亲。第二来是我惯曾为旅偏怜客。第三来也是我自己贪杯惜醉人。到那里呵也索费些精神。",
