                  "note": "底本：明《元曲选》本，参照中国古典戏曲资料库《元曲选·救风尘·第四折》。本折写宋引章持休书脱离周舍，周舍追赶并毁掉假休书；赵盼儿以预先准备的真休书和官府审理使骗局败露，安秀实与宋引章正式团圆。\n第四折先写周舍写休书，继而揭示赵盼儿准备真假两份文本的周密计划；公堂审理又把个人风月纠纷提升为强占婚姻、暴力和财产欺骗问题。李公弼判周舍杖六十、宋引章归安秀实为妻，赵盼儿“救风尘”的行动获得现实结果。\n题目与正名：题目为“安秀才花柳成花烛”，正名为“赵盼儿风月救风尘”。\n全剧评价：关汉卿没有把赵盼儿写成等待救援的女性，而是让她凭借经验、口才、胆识和行动完成救人。作品的喜剧结局建立在女性主动谋划和公堂裁判之上，因此具有鲜明的现实批判意义。",
