                  "note": "第四折前段先写李千金独居、思念子女，再写裴少俊中状元归来。裴少俊以功名和官职重新提出婚姻请求，李千金则以刑狱威胁、休书和裴家长辈的旧日态度回应。团圆尚未发生，第四折先让被休者保留拒绝和审查的权力。\n第四折中段没有让李千金因裴少俊中状元就立即复合，而是先让她重申羞辱、身份和责任问题。裴尚书带家人和子女出现后，酒礼、哭泣、玉簪银瓶等动作逐步推动她松动。复合的真正动力不是功名，而是道歉、子女和对旧事的重新承认。\n《墙头马上》四折结构可概括为：第一折墙头相遇、诗简传情；第二折月下赴约、私奔出走；第三折七年幽居、被休分离；第四折中状元返乡、认亲团圆。作品并非简单把爱情置于礼法之外，而是让李千金在家庭和社会秩序中不断为自身身份、婚姻和子女权利辩护。最终团圆虽然重新纳入家庭秩序，却不是对前三折冲突的抹除，而是经过女性坚持、子女介入和长辈道歉之后的重新协商。\n版本与来源：第四折曲牌和曲文据古文岛《裴少俊墙头马上》通行本及中国古典戏曲资料库《元曲选·墙头马上》交叉核对；典故和人物关系注释按曲文语境整理。",
