                  "note": "1. 张守珪出场：交代幽州边事和安禄山出征失利。\n2. 安禄山受审：他以勇力、辩才和“赤心”取得唐明皇注意，免去死罪。\n3. 安禄山入宫：杨贵妃收其为义子，安禄山以胡旋舞取悦帝妃。\n4. 张九龄与杨国忠进谏：二人预见安禄山可能成为唐室祸患，但未能阻止唐明皇任用。\n5. 外放漁阳：唐明皇将安禄山任为漁阳节度使，表面是限制和立功，实际上给了他军队和边地权力。\n灾难不是突然发生：剧本通过张九龄、杨国忠的预警和安禄山的性格表现，让后来的祸乱具有可追溯的政治原因。\n“识人”与“任人”问题：唐明皇并非完全不知道安禄山的危险，却因才艺、逢迎和个人判断继续任用他。\n宠爱与权力相连：杨贵妃收安禄山为义子，使亲密关系、宫廷宠幸和边镇军权连接起来。\n历史叙事的戏剧化：楔子不是正史摘录，而是把复杂的唐代政治史压缩为可在舞台上迅速识别的人物冲突。",
