                        "娉婷：形容女子姿态美好，这里指杨贵妃。",
                        "銮驾：皇帝乘坐的车驾，也可代指皇帝出行的仪仗。",
                        "晕庞儿：带有醉意或红晕的面容。庞儿，脸面。",
