                        "金鼎、银瓶：宫廷宴席和陈设中的贵重器物。",
                        "五生：七夕乞巧所用的五种应节植物或供物；不同整理本释义和字形可能有差异，需结合底本注本核对。",
                        "鹊桥会丹青幛：绘有牛郎织女鹊桥相会图景的屏障或帷幔。",
                        "蜘蛛儿：七夕乞巧习俗中以蜘蛛结网形态占验巧拙的物象。",
