                  "note": "第三折以残缺銮驾、荒凉山水和长安回望开场，随后通过父老劝太子、太子东还和六军停驻，把私人流亡转化为国家权力危机。前五曲尚未进入杨国忠、杨贵妃被杀的核心冲突，但已经完成三层推进：皇帝失去宫廷保护—百姓要求承担社稷责任—军队开始以集体力量逼迫皇帝。\n第三折中段从“杨国忠该杀”到“杨贵妃是否该死”逐步推进。杨国忠被杀后，六军仍不前进，说明军队要求的不是单一罪臣，而是要通过处理贵妃及其家族来完成政治清算。〔风入松〕回顾陈后主和《后庭花》，将当前危机放入“君主沉溺歌舞—宠妃受宠—国家败亡”的历史记忆中。\n〔胡十八〕写军权压迫，〔落梅风〕写帝王爱情无力，〔殿前欢〕写女性身体遭受毁灭，〔沽美酒〕写死亡时间被短暂拖延，〔太平令〕写最后的押送安排。贵妃之死并非单一“爱情悲剧”，而是帝国政治危机通过军队暴力落到女性身体上的结果。\n第三折从残缺銮驾和长安回望开始，经父老劝太子、六军哗变、杨国忠被杀、杨贵妃自尽，最后以遗物、临时葬埋和继续西行收束。其核心不是单纯写“帝妃生离死别”，而是把王朝政治危机转化为军队暴力、家庭牵连和私人遗物的连续场景。第一折长生殿的盟誓在第三折马嵬坡被逐层拆解：从誓言失效，到身体受辱，再到简葬和哭行。",
