                    "【滚绣球】这雨呵又不是救旱苗。润枯草。洒开花萼。谁望道秋雨如膏。向青翠条。碧玉梢。碎声儿𠛡剥。增百十倍歇和芭蕉。子管里珠连玉散飘千颗。平白地瀽瓮番盆下一宵。惹的人心焦。",
