                  "note": "本折又常称“寺警”。孙飞虎率兵围住普救寺，限期交出莺莺；莺莺先提出以自己换取全寺平安，随后又提出请退兵英雄成婚的办法；张生听到悬赏后主动提出退兵。文本依据古文岛《西厢记·第二本·第一折》核对。\n1. 莺莺的爱情相思在战争压力下迅速转化为家族责任和生死选择。\n2. 老夫人提出“退兵者与小姐成婚”的条件，为张生介入危机提供了公开、正当的机会。\n3. 莺莺主动提出“与英雄结婚”，说明她并非完全被动等待，而是在极端情境中设计自己的婚姻出路。\n4. 孙飞虎以美貌为理由围寺，表现女性被物化为政治和军事争夺对象；张生的退敌则构成对这一逻辑的反转。",
