                    "【正宫·端正好】不念《法华经》，不礼梁皇忏，颩了僧伽帽，袒下我这偏衫。杀人心逗起英雄胆，两只手将乌龙尾钢椽攥。",
                    "【正宫·滚绣球】（第一次）非是我贪，不是我敢，知他怎生唤做打参，不踏步直杀出虎窟龙潭。非是我搀，不是我揽，这些时吃菜馒头委实口淡，五千人也不索灸煎腔子里热血权消渴，肺腑内生心且解馋，有甚腌臜！",
                    "【正宫·叨叨令】浮沙羹、宽片粉添些杂糁，酸黄韭、烂豆腐休调啖，万余斤黑面从教暗，我将这五千人做一顿馒头馅。是必休误了也么哥！休误了也么哥！包残馀肉把青盐蘸。",
                    "【正宫·倘秀才】你那里问小僧敢去也那不敢，我这里启大师用喒。你道是飞虎声名播斗南；那厮能淫欲，会贪婪，诚何以堪！",
                    "【正宫·滚绣球】（第二次）我经文也不会谈，逃禅也懒去参；戒刀头近新来钢蘸，铁棒上无半星儿土渍尘缄。别的都僧不僧、俗不俗，女不女、男不男，则会斋得饱也则去那僧房中胡渰，那里管焚烧了兜率也似伽蓝。则为那善文能武人千里，凭著这济困扶危书一缄，有勇无惭。",
                    "【正宫·白鹤子】着几个小沙弥把幢幡宝盖擎，壮行者将杆棒镬叉担，你排阵脚将众僧安，我撞钉子把贼兵来探。",
                    "【正宫·白鹤子】二、【一】远的破开步将铁棒颩，近的顺手把戒刀钐；有小的提起来将脚尖躔，有大的扳下来把髑髅勘。瞅一瞅古都都翻了海波，滉一滉厮琅琅震动山岩；脚踏得赤力力地轴摇，手扳得忽剌剌天关撼。",
                    "【正宫·耍孩儿】我从来驳驳劣劣，也不曾忑忑忐忐，打熬成不厌天生敢。我从来斩钉截铁常居一，不似恁惹草拈花没掂三。劣性子人皆惨，舍著命提刀仗剑，更怕甚勒马停骖。",
                    "【正宫·耍孩儿】二我从来欺硬怕软，吃苦不甘，你休只因亲事胡扑掩。若是杜将军不把干戈退，张解元干将风月担，我将不志诚的言词赚。倘或纰缪，倒大羞惭。",
                    "【正宫·收尾】您与我助威风擂几声鼓，仗佛力呐一声喊。绣旗下遥见英雄俺，我教那半万贼兵吓唬破胆。本节说明：《西厢记》第二本第二折已完成惠明曲牌系统、完整曲词、注释和版本边界说明；下一步补录第二本楔子及后续曲折。"
