                  "note": "老夫人误信郑恒谎言，准备把莺莺嫁给郑恒。张生奉圣旨回乡，夫人却以为他另娶卫尚书之女。红娘、法本长老和杜确先后为张生作证，证明郑恒诬告。郑恒自知阴谋败露，触树自尽。张生与莺莺在杜确等人的见证下成婚，最后以“愿普天下有情的都成了眷属”收束全剧。",
