                    "【竹枝歌】打听为官折了桂枝。别取了新婚甚意思。着妹妹目下恨难支。把哥哥闲传示。则问这小妮子。被我都痴痴的。扯做纸条儿。",
                    "【水仙子】想当日暂停车棹饮离尊。生恐怕千里关山劳梦频。没揣的灵犀一点潜相引。便一似生个身外身。一般般两个佳人。那一个跟他取应。这一个淹煎病损。母亲。则这是倩女离魂。"
