                  "note": "底本：明《元曲选》本，参照中国古典戏曲资料库《元曲选·倩女离魂·第四折》。第四折写王文举携“魂旦”衣锦还乡，岳母误以为妖魅；魂旦进入病榻，与正旦身体合一，倩女离魂的奇异情节最终获得家庭和婚姻层面的承认。\n第四折依次完成四个动作：返乡途中回忆旧情；岳母将魂旦视为妖魅；魂旦进入病榻与正旦身体合一；倩女说明离魂缘由并获得婚姻承认。结尾由夫人决定为夫妻正式成亲，并授予官诰，奇幻事件被纳入家庭和社会秩序之中。全剧因而形成“相思离魂—误会加深—魂魄归体—婚姻确认”的闭合结构。\n题目与正名：题目为“调素琴王生写恨”，正名为“迷青琐倩女离魂”。",
